INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-BAS-C-020', 'W', 'bas', 'C', '{"a":"What would make the policy more equitable?","parts":["A flexible deadline",null,null,null,null,null,null,null,"."],"chunks":["applicants","beyond their control","depending","depends","on institutions","to required documents","whose access","would help"],"focus":"Whose + согласование"}', '[["would help","applicants","whose access","to required documents","depends","on institutions","beyond their control"]]', '["Applicants whose access … depends on institutions. Подлежащее access — ед. ч., поэтому depends."]', '["Build a Sentence"]', 1, 'active', 1793467630956, 1793467630956)
