INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-A-001', 'W', 'eml', 'A', '{"to":"Ms. Patel, Librarian","subject":"Damaged library book","situation":"You borrowed a book from the university library. Yesterday you spilled coffee on it, and some pages are now stained. The book is due back next week.","bullets":["Explain what happened to the book","Ask what you should do now","Offer a way to solve the problem"]}', 'null', 'null', 'null', -1, 'active', 1793467630956, 1793467630956)
