INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-005', 'W', 'eml', 'B', '{"to":"City Parks Department","subject":"Suggestion for Riverside Park","situation":"You often go running in Riverside Park in the evening. The path is very dark after sunset, and several runners have nearly fallen.","bullets":["Describe the problem","Explain why it matters to park users","Suggest a possible solution"]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
