INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-006', 'W', 'eml', 'B', '{"to":"Dr. Nguyen","subject":"Research assistant position","situation":"Dr. Nguyen, a psychology professor, posted an announcement looking for a student research assistant for the summer. You took her course last year and enjoyed it.","bullets":["Explain why you are interested in the position","Describe relevant experience or skills","Ask a question about the responsibilities"]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
