INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-007', 'W', 'eml', 'B', '{"to":"Customer Service, Brightline Electronics","subject":"Faulty headphones","situation":"You ordered wireless headphones online. When they arrived, the left side did not work. You have already tried charging them fully.","bullets":["Describe the problem with the product","Explain what you have already tried","Say what you would like the company to do"]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
