INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-008', 'W', 'eml', 'B', '{"to":"Professor Adams","subject":"Feedback on my essay","situation":"You received a lower grade than you expected on an essay for Professor Adams''s sociology course. The comments say that your argument was unclear, but you are not sure what to improve.","bullets":["Thank the professor for the comments","Explain which part you do not understand","Ask for a meeting or specific advice"]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
