INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-001', 'W', 'eml', 'C', '{"to":"Editorial Board, The Campus Weekly","subject":"Response to your article on study spaces","situation":"The student newspaper published an article claiming that students rarely use the library''s quiet study rooms and that the rooms should be turned into a café. You use the rooms regularly and disagree.","bullets":["Explain your reaction to the article","Give evidence or examples that challenge its claim","Propose an alternative that could satisfy different students"]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-002', 'W', 'eml', 'C', '{"to":"Ms. Brooks, Internship Supervisor","subject":"Workload during exams","situation":"You are doing a part-time internship at a marketing company. Your final exams start in two weeks, and your supervisor has just given you a large new assignment due at the same time.","bullets":["Show that you value the assignment","Explain the conflict with your exams","Suggest a realistic arrangement"]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-003', 'W', 'eml', 'C', '{"to":"Housing Committee","subject":"Proposed quiet hours","situation":"The residence hall committee is proposing quiet hours from 9 p.m. to 9 a.m. every day. Some residents support the idea, but others, including you, think it is too strict.","bullets":["State your opinion of the proposal","Explain how it would affect residents like you","Suggest a compromise"]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-004', 'W', 'eml', 'C', '{"to":"Mr. Kowalski, Program Director","subject":"Study abroad credits","situation":"You recently returned from a semester abroad. Your university has accepted only two of the four courses you took, even though you received approval before leaving.","bullets":["Explain the situation clearly","Refer to the approval you received","Request a specific action and timeline"]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-005', 'W', 'eml', 'C', '{"to":"Professor Mendes","subject":"Guest speaker for our club","situation":"You lead the environmental club at your university. Professor Mendes recently published a book on urban ecology, and the club would like to invite her to speak.","bullets":["Introduce yourself and the club","Explain why her work interests the members","Describe the event and ask about her availability"]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-006', 'W', 'eml', 'C', '{"to":"Facilities Manager","subject":"Accessibility of the new lecture hall","situation":"The university has opened a new lecture hall. A friend of yours who uses a wheelchair has found that the only accessible entrance is often locked in the evening.","bullets":["Describe the problem you have observed","Explain its consequences for students","Recommend steps the university could take"]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-001', 'W', 'dsc', 'B', '{"course":"Education","professor":{"name":"Dr. Gomez","text":"Many universities now record lectures and post them online. Some educators think this helps students learn because they can review difficult material at their own pace. Others worry that students stop attending class and lose the benefits of live discussion. What do you think? Should universities record all lectures and make them available online? Why or why not?"},"students":[{"name":"Kelly","text":"I think recordings are very useful. When a professor speaks quickly, I can pause the video and take better notes. Students who are sick or who work part-time also don''t fall behind."},{"name":"Andrew","text":"I disagree. If every lecture is online, many students will just stay home, and class discussions will become empty. Asking questions in person is an important part of learning."}]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-002', 'W', 'dsc', 'B', '{"course":"Urban Studies","professor":{"name":"Professor Tan","text":"Cities around the world are trying to reduce traffic in their downtown areas. One approach is to make public transportation completely free. Supporters say this would encourage people to leave their cars at home. Critics argue that the money would be better spent improving service. If you were advising a city government, would you recommend free public transportation? Explain your view."},"students":[{"name":"Maria","text":"Free transportation is a great idea. Many people drive because bus tickets add up over a month. If buses were free, more people would try them, and there would be less pollution."},{"name":"Jason","text":"I''m not convinced. Price isn''t the main problem where I live—the buses are slow and come only every half hour. A free bus that never arrives on time won''t change anyone''s habits."}]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-003', 'W', 'dsc', 'B', '{"course":"Business","professor":{"name":"Dr. Williams","text":"Some companies have started offering employees a four-day work week with the same pay, as long as the work gets done. Supporters say workers become happier and more productive. Others believe it is unrealistic for many types of businesses. Do you think a four-day work week is a good idea for most companies? Why or why not?"},"students":[{"name":"Priya","text":"I think it could work well. People who have more rest are more focused, so they might get the same amount done in four days. It would also help companies attract good workers."},{"name":"Tom","text":"It sounds nice, but it doesn''t fit every job. Hospitals, stores, and restaurants need staff every day. Those businesses would have to hire more people, which could be very expensive."}]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-004', 'W', 'dsc', 'B', '{"course":"Psychology","professor":{"name":"Professor Ahmed","text":"This week we are discussing how people form habits. Some researchers recommend changing one small habit at a time, while others suggest that big life changes, such as moving to a new city, are the best moment to change many habits at once. Which approach do you think is more effective for building good habits, and why?"},"students":[{"name":"Lucas","text":"Small changes are more realistic. When I tried to change everything at once in January, I gave up after a week. Starting with one habit, like going to bed earlier, is easier to keep."},{"name":"Hannah","text":"I think big changes can actually help. When I moved to college, I had no old routine, so it was easy to start exercising and cooking. A new environment gives you a fresh start."}]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-005', 'W', 'dsc', 'B', '{"course":"Environmental Science","professor":{"name":"Dr. Okafor","text":"Many supermarkets now charge customers a small fee for plastic bags. The goal is to reduce plastic waste, but some people say the fee is unfair to low-income shoppers or simply moves the problem elsewhere. In your opinion, is charging for plastic bags an effective way to protect the environment? Explain why."},"students":[{"name":"Sofia","text":"Yes, I think it works. In my town, people started bringing their own bags almost immediately after the fee was introduced. Even a small cost makes people think about their choices."},{"name":"Daniel","text":"I''m doubtful. Many people now buy plastic trash bags instead of reusing shopping bags, so the total amount of plastic may not change much. We need bigger solutions."}]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-006', 'W', 'dsc', 'B', '{"course":"Sociology","professor":{"name":"Professor Hill","text":"Volunteering is often seen as an important part of being a good citizen. Some high schools now require students to complete a certain number of volunteer hours before they can graduate. Do you think schools should make volunteering a graduation requirement? Why or why not?"},"students":[{"name":"Emma","text":"I support the requirement. Many teenagers never think about volunteering until someone asks them to. Once they try it, they often discover causes they care about."},{"name":"Ryan","text":"Forcing people to volunteer goes against the whole idea. Students will just do the minimum to get the hours, and organizations may end up with helpers who don''t want to be there."}]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-007', 'W', 'dsc', 'B', '{"course":"Media Studies","professor":{"name":"Dr. Russo","text":"More and more people get their news from short videos on social media rather than from newspapers or television. Some say this makes news more accessible, especially for young people. Others worry that short videos cannot explain complex issues properly. What is your view? Is getting news from short videos a positive or negative trend?"},"students":[{"name":"Aiko","text":"I see it as positive. Many of my friends never read newspapers, but they watch short news videos every day. At least they know what is happening in the world."},{"name":"Marcus","text":"The problem is that a one-minute video can''t give context. People see a dramatic clip and form strong opinions without understanding the full story. That can make debates more extreme."}]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-001', 'W', 'dsc', 'C', '{"course":"Economics","professor":{"name":"Professor Lindqvist","text":"Governments sometimes provide financial support to industries they consider strategically important, such as renewable energy or computer chip manufacturing. Proponents argue that early support helps new industries become competitive. Critics contend that governments are poor at choosing winners and that subsidies distort markets. Should governments subsidize specific industries? Use reasons and examples to support your position."},"students":[{"name":"Fatima","text":"I think targeted support is justified when the benefits extend beyond a single company. Solar power became affordable partly because early subsidies allowed producers to scale up, and now the whole economy benefits from cheaper energy."},{"name":"Oliver","text":"Subsidies often end up protecting inefficient firms long after they should have adapted. Once an industry receives money, it lobbies to keep it. I''d prefer governments to fund basic research and let companies compete."}]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-002', 'W', 'dsc', 'C', '{"course":"Philosophy","professor":{"name":"Dr. Haddad","text":"Artificial intelligence tools can now write essays, summarize readings, and solve problems. Some instructors want to ban these tools in coursework, while others believe students should learn to use them responsibly as they will in the workplace. How do you think universities should respond to AI tools in student assignments? Explain your reasoning."},"students":[{"name":"Grace","text":"Banning them is unrealistic and probably impossible to enforce. Universities should redesign assignments so that students have to show their own reasoning, for example through drafts or oral explanations, while still allowing AI for brainstorming."},{"name":"Victor","text":"I think some courses should ban them, at least at the beginning. If students rely on AI before they''ve developed basic writing skills, they''ll never learn to structure an argument themselves."}]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-003', 'W', 'dsc', 'C', '{"course":"Public Health","professor":{"name":"Professor Lin","text":"Some cities have introduced taxes on sugary drinks to reduce health problems such as obesity and diabetes. Evidence suggests that consumption falls after such taxes are introduced, but critics say the taxes place a heavier burden on low-income families and limit personal choice. Do you think taxes on sugary drinks are a good public health policy? Why or why not?"},"students":[{"name":"Noah","text":"The evidence is persuasive. If purchases drop and the revenue is spent on health programs or free drinking water in schools, low-income communities actually benefit the most."},{"name":"Isabella","text":"I''m uncomfortable with policies that change behavior by making daily life more expensive for people with the least money. Education and better access to healthy food would address the causes rather than punishing the symptoms."}]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-004', 'W', 'dsc', 'C', '{"course":"Architecture","professor":{"name":"Dr. Moreau","text":"When historic buildings are no longer used for their original purpose, cities must decide what to do with them. Some argue that these buildings should be carefully preserved as they are, while others believe they should be adapted for new uses, even if this means significant changes to their interiors. Which approach do you favor, and why?"},"students":[{"name":"Elena","text":"Adaptation keeps buildings alive. An old factory turned into apartments or a library is used every day, and the community stays connected to its history in a practical way."},{"name":"James","text":"Some changes destroy exactly what made a building valuable. Once original interiors are removed, they can''t be restored. I think at least the most significant buildings should be protected from major alterations."}]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-005', 'W', 'dsc', 'C', '{"course":"Linguistics","professor":{"name":"Professor Diaz","text":"Many minority languages around the world are losing speakers as younger generations shift to more widely used languages. Some people believe that governments should invest heavily in preserving these languages through schools and media. Others argue that language change is natural and that resources should go elsewhere. What is your position on this issue?"},"students":[{"name":"Amara","text":"A language carries knowledge, stories, and ways of seeing the world that can''t be fully translated. When it disappears, that knowledge is lost for everyone, so public investment is worth it."},{"name":"Ethan","text":"Preservation programs often fail if families themselves don''t see a benefit in using the language. Rather than large government programs, support should go to communities that actively want to keep their language."}]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-006', 'W', 'dsc', 'C', '{"course":"Business Ethics","professor":{"name":"Dr. Carter","text":"Some companies publish the salaries of all their employees so that everyone can see what others earn. Supporters say this transparency reduces unfair pay gaps. Opponents worry that it creates conflict and invades employees'' privacy. Should companies make all salaries public within the organization? Explain your view with reasons and examples."},"students":[{"name":"Mei","text":"Transparency forces companies to justify their decisions. Pay gaps between men and women, for example, are much harder to maintain when everyone can see the numbers."},{"name":"Liam","text":"Salaries depend on many factors that aren''t visible, such as negotiation or special skills. Publishing them could lead to resentment and make employees feel judged by colleagues."}]}', 'null', 'null', 'null', 1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-001', 'W', 'dsc', 'A', '{"course":"Education","professor":{"name":"Professor Brown","text":"Some schools give students a lot of homework every day. Other schools give very little homework so that students have time for sports, hobbies, and family. Which do you think is better for students: more homework or less homework? Why?"},"students":[{"name":"Mia","text":"I think more homework is better. Practicing at home helps students remember what they learned in class, and it prepares them for exams."},{"name":"Leo","text":"I prefer less homework. Students are already tired after school. They need time to relax, play sports, and spend time with their families."}]}', 'null', 'null', 'null', -1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-002', 'W', 'dsc', 'A', '{"course":"Health","professor":{"name":"Dr. Silva","text":"Many people use their phones right before they go to sleep. Some experts say this is bad for sleep, but others think it is a good way to relax. Should people stop using their phones one hour before bed? Why or why not?"},"students":[{"name":"Chloe","text":"Yes, I think so. When I read on my phone at night, I fall asleep much later. Reading a paper book helps me sleep better."},{"name":"Sam","text":"I don''t agree. Listening to music or watching a short video on my phone helps me relax after a busy day. It depends on what you do with the phone."}]}', 'null', 'null', 'null', -1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-003', 'W', 'dsc', 'A', '{"course":"Sociology","professor":{"name":"Professor Kim","text":"Some people like to live in big cities, while others prefer small towns. Each place has advantages. If you could choose, would you prefer to live in a big city or a small town? Explain why."},"students":[{"name":"Olivia","text":"I would choose a big city. There are more jobs, museums, and restaurants, and public transportation makes it easy to go everywhere."},{"name":"Ben","text":"I prefer small towns. They are quieter and safer, and people know their neighbors. Life is less stressful when everything is close."}]}', 'null', 'null', 'null', -1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-004', 'W', 'dsc', 'A', '{"course":"Business","professor":{"name":"Dr. Evans","text":"Many students have part-time jobs while they are studying at university. Some people think this is a good experience. Others think students should focus only on their studies. Is it a good idea for university students to have part-time jobs? Why or why not?"},"students":[{"name":"Zoe","text":"Yes, it is a good idea. Students learn to manage money and time, and they get experience that helps them find a job after graduation."},{"name":"Adam","text":"I think students should focus on studying. A job takes a lot of time and energy, and grades can become worse."}]}', 'null', 'null', 'null', -1, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-008', 'W', 'dsc', 'B', '{"course":"Technology","professor":{"name":"Professor Reyes","text":"Online shopping has become extremely popular, and many small local stores have closed as a result. Some people say this is simply progress and that customers benefit from lower prices and more choice. Others think communities lose something important when local shops disappear. What is your opinion? Should people make an effort to shop at local stores?"},"students":[{"name":"Nina","text":"I try to shop locally when I can. Local stores create jobs in the neighborhood and make streets more lively. Saving a few dollars online isn''t worth losing that."},{"name":"Chris","text":"Most people simply can''t afford to pay more. Online shopping saves time and money, especially for busy families. Stores need to adapt instead of expecting customers to support them."}]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-009', 'W', 'dsc', 'B', '{"course":"Education","professor":{"name":"Dr. Park","text":"Some universities require all first-year students to take courses outside their major, such as art, history, or science. Supporters say this gives students a broader education. Others think students should be free to focus on their chosen field from the start. Should universities require students to take courses outside their major? Why or why not?"},"students":[{"name":"Rachel","text":"Yes. I took a philosophy course I didn''t want to take, and it completely changed the way I think about my engineering projects. You can''t know what''s useful until you try it."},{"name":"Kevin","text":"University is expensive, and students should be able to spend their time and money on what they actually need for their careers. Required courses can feel like a waste."}]}', 'null', 'null', 'null', 0, 'active', 1793467630956, 1793467630956)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
